+    OP_CHECK_NULL_WITH_CONTEXT(context, inputOut);
+    auto outShape = inputOut->GetStorageShape();
+
+    auto outputY = context->GetOutputShape(0);
+    OP_CHECK_NULL_WITH_CONTEXT(context, outputY);
