+struct SeluGradCompileInfo {};
+
+// Tiling 注册入口
+IMPL_OP_OPTILING(SeluGrad).Tiling(SeluGradTilingFunc).TilingParse<SeluGradCompileInfo>(TilingParseForSeluGrad);
+
