+static ge::graphStatus InferShape4SeluGrad(gert::InferShapeContext* context)
+{
+    const gert::Shape* gradShape = context->GetInputShape(0);
+    OP_CHECK_NULL_WITH_CONTEXT(context, gradShape);
+
+    const gert::Shape* outShape = context->GetInputShape(1);
+    OP_CHECK_NULL_WITH_CONTEXT(context, outShape);
+
+    gert::Shape* yShape = context->GetOutputShape(0);
+    OP_CHECK_NULL_WITH_CONTEXT(context, yShape);
+
+    // 处理 rank=0 标量
+    if (gradShape->GetDimNum() == 0 && outShape->GetDimNum() == 0) {
+        // 两个标量输入，输出也是标量
+        return ge::GRAPH_SUCCESS;
+    }
+
+    // 处理 rank=0 标量 + tensor 广播
+    if (gradShape->GetDimNum() == 0) {
+        *yShape = *outShape;
+        return ge::GRAPH_SUCCESS;
+    }
+    if (outShape->GetDimNum() == 0) {
+        *yShape = *gradShape;
+        return ge::GRAPH_SUCCESS;
+    }
+
+    // numpy broadcast 推导
+    OP_CHECK_IF(!NumpyBroadcastShape(*gradShape, *outShape, *yShape),
+                OP_LOGE(context, "Shape broadcast failed"),
+                return ge::GRAPH_FAILED);
+
+    return ge::GRAPH_SUCCESS;
+}
