+extern "C" __global__ __aicore__ void swiglu_group(GM_ADDR x, GM_ADDR weight, GM_ADDR groupIndex, GM_ADDR y,
+    GM_ADDR workspace, GM_ADDR tiling)
+{
+    if (workspace == nullptr) {
