+    ge::DataType xDtype = ge::DT_FLOAT16;
+    ge::DataType yDtype = ge::DT_FLOAT16;
+    ge::DataType weightDtype = ge::DT_FLOAT;
+    ge::DataType groupIndexDtype = ge::DT_INT64;
