+    copyParams.srcStride = 0;
+    copyParams.dstStride = 0;
+    DataCopyPadParams padParams{false, 0, 0, 0};
+    DataCopyPad(weightLocalTensor, weightGm[tokenIdx], copyParams, padParams);
+    weightQueue.EnQue<float>(weightLocalTensor);
+}
