+namespace optiling {
+
+using namespace Ops::NN::OpTiling;
+
+constexpr int64_t PER_CORE_MIN = 1024;
+constexpr uint32_t DCACHE_SIZE = 128 * 1024;
+constexpr uint32_t STATIC_UB_ESTIMATE = 0;
+
+struct ThresholdCompileInfo {};
+
+static ge::graphStatus SetUbAndTilingKey(gert::TilingContext* context, uint64_t ubSize)
+{
+    OP_CHECK_IF((ubSize <= DCACHE_SIZE + STATIC_UB_ESTIMATE),
+        OP_LOGE(context, "ubSize %lu <= DCACHE_SIZE + STATIC_UB_ESTIMATE", ubSize),
+        return ge::GRAPH_FAILED);
+    auto res = context->SetLocalMemorySize(static_cast<uint32_t>(ubSize - DCACHE_SIZE - STATIC_UB_ESTIMATE));
+    OP_CHECK_IF((res != ge::GRAPH_SUCCESS),
+        OP_LOGE(context, "SetLocalMemorySize failed, ubSize=%lu, DCACHE_SIZE=%u", ubSize, DCACHE_SIZE),
+        return ge::GRAPH_FAILED);
+
+    uint64_t tilingKey = GET_TPL_TILING_KEY(THRESHOLD_SCH_MODE_0);
+    context->SetTilingKey(tilingKey);
+    return ge::GRAPH_SUCCESS;
+}
+
+static ge::graphStatus ThresholdTilingFunc(gert::TilingContext* context)
+{
+    // 1. Get platform info
+    auto ascendcPlatform = platform_ascendc::PlatformAscendC(context->GetPlatformInfo());
+    int64_t physicalCoreNum = ascendcPlatform.GetCoreNumAiv();
+    OP_CHECK_IF(physicalCoreNum == 0, OP_LOGE(context, "coreNum is 0"), return ge::GRAPH_FAILED);
+    uint64_t ubSize = 0;
+    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
+
+    // 2. Get input shape
+    auto inputX = context->GetInputShape(0);
+    OP_CHECK_NULL_WITH_CONTEXT(context, inputX);
+    auto inputShapeX = EnsureNotScalar(inputX->GetStorageShape());
+    int64_t totalElements = inputShapeX.GetShapeSize();
+
+    // 3. Get threshold attribute (Float type, default 0.0)
+    float threshold = 0.0f;
+    const auto* attrs = context->GetAttrs();
+    if (attrs != nullptr && attrs->GetAttrNum() > 0) {
+        const float* thrPtr = attrs->GetFloat(0);
+        if (thrPtr != nullptr) {
+            threshold = *thrPtr;
+        }
+    }
+
+    // 4. Get workspace size (no user workspace, only system workspace)
+    uint64_t sysWorkspaceSize = ascendcPlatform.GetLibApiWorkSpaceSize();
+    size_t* currentWorkspace = context->GetWorkspaceSizes(1);
+    OP_CHECK_NULL_WITH_CONTEXT(context, currentWorkspace);
+    currentWorkspace[0] = static_cast<size_t>(sysWorkspaceSize);
+
+    // 5. Calculate TilingData
+    ThresholdTilingData tiling;
+    tiling.totalElements = totalElements;
+    tiling.threshold = threshold;
+
+    // Zero-dim protection: when totalElements is 0, kernel does nothing, set needCoreNum=1
+    if (totalElements == 0) {
+        tiling.needCoreNum = 1;
+        context->SetBlockDim(1);
+        (*context->GetTilingData<ThresholdTilingData>()) = tiling;
+
+        return SetUbAndTilingKey(context, ubSize);
+    }
+
+    // Core splitting with PER_CORE_MIN protection
+    int64_t perCoreElements = Ops::Base::CeilDiv(totalElements, physicalCoreNum);
+    if (perCoreElements < PER_CORE_MIN) {
+        perCoreElements = PER_CORE_MIN;
+    }
+    int64_t needCoreNum = Ops::Base::CeilDiv(totalElements, perCoreElements);
+    // Safety: needCoreNum must be at least 1 for non-empty input
+    if (needCoreNum < 1) {
+        needCoreNum = 1;
+    }
+    tiling.needCoreNum = static_cast<int32_t>(needCoreNum);
+
+    // 6. Set TilingData
+    context->SetBlockDim(tiling.needCoreNum);
+    (*context->GetTilingData<ThresholdTilingData>()) = tiling;
+
+    return SetUbAndTilingKey(context, ubSize);
+}
+
+static ge::graphStatus TilingParseForThreshold([[maybe_unused]] gert::TilingParseContext* context)
+{
+    return ge::GRAPH_SUCCESS;
+}
+
+IMPL_OP_OPTILING(Threshold).Tiling(ThresholdTilingFunc).TilingParse<ThresholdCompileInfo>(TilingParseForThreshold);
+
+} // namespace optiling

