+constexpr int64_t THRESHOLD_ATTR_IDX = 0;
+constexpr float DEFAULT_THRESHOLD = 1.0f;
+
+// 5.0 CheckBroadcastShape — 补 1 后逐维检查 broadcast 兼容性：同维非 1 大小必须一致
+static bool CheckBroadcastShape(
+    const std::vector<std::vector<int64_t>>& padded_in,
+    const std::vector<std::vector<int64_t>>& padded_out,
+    int64_t max_rank)
+{
+    for (int64_t d = 0; d < max_rank; d++) {
+        int64_t ref = -1;
+        for (size_t i = 0; i < padded_in.size(); i++) {
+            if (padded_in[i][d] != 1) {
+                if (ref == -1) ref = padded_in[i][d];
+                else if (padded_in[i][d] != ref) {
+                    OP_LOGE("PadAndSqueeze", "dim %d broadcast incompatible: input[%d] size %d != %d",
+                            (int)d, (int)i, (int)padded_in[i][d], (int)ref);
+                    return false;
+                }
+            }
+        }
+        for (size_t i = 0; i < padded_out.size(); i++) {
+            if (padded_out[i][d] != 1) {
+                if (ref == -1) ref = padded_out[i][d];
+                else if (padded_out[i][d] != ref) {
+                    OP_LOGE("PadAndSqueeze", "dim %d broadcast incompatible: output[%d] size %d != %d",
+                            (int)d, (int)i, (int)padded_out[i][d], (int)ref);
+                    return false;
+                }
+            }
+        }
+    }
+    return true;
+}
+
+bool PadAndSqueeze(
+    const std::vector<std::vector<int64_t>>& input_shapes,
+    const std::vector<std::vector<int64_t>>& output_shapes,
+    std::vector<int64_t>&                    maximum_bro_shape,
+    std::vector<std::vector<int64_t>>&       normal_input_shapes,
+    std::vector<std::vector<int64_t>>&       normal_output_shapes)
+{
+    int64_t num_inputs  = (int64_t)input_shapes.size();
+    int64_t num_outputs = (int64_t)output_shapes.size();
+    int64_t max_rank = 0;
+    for (auto& s : input_shapes)  max_rank = std::max(max_rank, (int64_t)s.size());
+    for (auto& s : output_shapes) max_rank = std::max(max_rank, (int64_t)s.size());
+    auto pad = [&](const std::vector<int64_t>& s) {
+        std::vector<int64_t> p;
+        p.assign(max_rank - (int64_t)s.size(), 1);
+        p.insert(p.end(), s.begin(), s.end());
+        return p;
+    };
+    std::vector<std::vector<int64_t>> padded_in(num_inputs), padded_out(num_outputs);
+    for (int64_t i = 0; i < num_inputs; i++)  padded_in[i]  = pad(input_shapes[i]);
+    for (int64_t i = 0; i < num_outputs; i++) padded_out[i] = pad(output_shapes[i]);
+    // 校验 — 补 1 后逐维 broadcast 兼容性，不兼容返回 false（调用方转 GRAPH_FAILED）
+    if (!CheckBroadcastShape(padded_in, padded_out, max_rank)) return false;
+    maximum_bro_shape.clear();
+    normal_input_shapes.assign(num_inputs, std::vector<int64_t>());
+    normal_output_shapes.assign(num_outputs, std::vector<int64_t>());
+    for (int64_t d = 0; d < max_rank; d++) {
+        bool all_one = true;
+        int64_t max_dim = 0;
+        for (int64_t i = 0; i < num_inputs; i++) { if (padded_in[i][d] != 1) all_one = false; max_dim = std::max(max_dim, padded_in[i][d]); }
+        for (int64_t i = 0; i < num_outputs; i++) { if (padded_out[i][d] != 1) all_one = false; max_dim = std::max(max_dim, padded_out[i][d]); }
+        if (!all_one) {
+            maximum_bro_shape.push_back(max_dim);
+            for (int64_t i = 0; i < num_inputs; i++)  normal_input_shapes[i].push_back(padded_in[i][d]);
+            for (int64_t i = 0; i < num_outputs; i++) normal_output_shapes[i].push_back(padded_out[i][d]);
+        }
+    }
+    if (maximum_bro_shape.empty()) {
+        maximum_bro_shape.push_back(1);
+        for (int64_t i = 0; i < num_inputs; i++)  normal_input_shapes[i].push_back(1);
+        for (int64_t i = 0; i < num_outputs; i++) normal_output_shapes[i].push_back(1);
+    }
+    return true;
+}
+
+bool FindSplitAxis(const std::vector<int64_t>& max_bro_shape,
+    int64_t ub_per_core, int64_t phys_nodes, SplitResult& out)
+{
+    if (phys_nodes <= 0) { return false; }
+    int64_t per_buf_bytes = (ub_per_core / phys_nodes) & ~31LL;
+    int64_t per_buf_elems = per_buf_bytes / 4;  // 统一 FP32
+    int64_t rank = (int64_t)max_bro_shape.size();
+    int64_t inner = 1;
+    for (int64_t k = rank - 1; k >= 0; k--) {
+        if (max_bro_shape[k] * inner > per_buf_elems) {
+            out.a_i = per_buf_elems / inner;
+            out.a_o = (max_bro_shape[k] + out.a_i - 1) / out.a_i;
+            int64_t rem = max_bro_shape[k] % out.a_i;
+            out.a_i_tail = (rem == 0) ? out.a_i : rem;
+            out.axis = k;
+            return true;
+        }
+        if (k == 0) { out.axis = 0; out.a_i = max_bro_shape[0]; out.a_o = 1; out.a_i_tail = max_bro_shape[0]; return true; }
+        inner *= max_bro_shape[k];
+    }
+    return true;
+}
+
+bool MultiCoreSplit(const std::vector<int64_t>& max_bro_shape,
+    const SplitResult& ub_split, int64_t max_cores, MultiCoreResult& out)
+{
+    int64_t k = ub_split.axis, outer_prod = 1;
+    for (int64_t j = 0; j < k; j++) outer_prod *= max_bro_shape[j];
+    out.total_tiles = outer_prod * ub_split.a_o;
+    out.num_cores   = (out.total_tiles < max_cores) ? out.total_tiles : max_cores;
+    out.tiles_main  = out.total_tiles / out.num_cores;
+    out.cores_tail  = out.total_tiles % out.num_cores;
+    return true;
+}
+
+bool PrecomputeStrides(const std::vector<int64_t>& s, std::vector<int64_t>& strides) {
+    int64_t rank = (int64_t)s.size();
+    strides.assign(rank, 0);
+    for (int64_t d = rank - 1; d >= 0; d--) {
+        if (s[d] == 1) { strides[d] = 0; continue; }
+        int64_t prod = 1;
+        for (int64_t j = d + 1; j < rank; j++) prod *= s[j];
+        strides[d] = prod;
+    }
+    return true;
+}
+
+} // namespace tgv2d
+
+struct ThresholdGradV2DCompileInfo { uint64_t coreNum; uint64_t ubSize; };
+
+static std::string Arr2String(const int64_t* arr, int64_t n) {
+    std::ostringstream oss; oss << "[";
+    if (n > 0) { for (int64_t i = 0; i < n - 1; ++i) oss << arr[i] << ","; oss << arr[n - 1]; }
+    oss << "]"; return oss.str();
+}
+
+class ThresholdGradV2DTilingImpl {
+public:
+    explicit ThresholdGradV2DTilingImpl(gert::TilingContext* ctx) : ctx_(ctx) {}
+
+    ge::graphStatus RunTiling() {
+        ge::graphStatus ret = GetShapeInfo();
+        if (ret != ge::GRAPH_SUCCESS) return ret;
+        int64_t total_out = 1;
+        for (auto d : raw_output_shapes_[0]) total_out *= d;
+        if (total_out == 0) { ctx_->SetBlockDim(1); ctx_->SetTilingKey(GET_TPL_TILING_KEY(THRESHOLD_GRAD_V2_D_RANK_4)); return ge::GRAPH_SUCCESS; }
+        if (rank_ <= 4) { ret = DoTilingAndSet<4>(); ctx_->SetTilingKey(GET_TPL_TILING_KEY(THRESHOLD_GRAD_V2_D_RANK_4)); }
+        else            { ret = DoTilingAndSet<8>(); ctx_->SetTilingKey(GET_TPL_TILING_KEY(THRESHOLD_GRAD_V2_D_RANK_8)); }
+        return ret;
+    }
+
+private:
+    ge::graphStatus GetShapeInfo() {
+        fe::PlatFormInfos* platformInfo = ctx_->GetPlatformInfo();
+        OP_CHECK_NULL_WITH_CONTEXT(ctx_, platformInfo);
+        auto ap = platform_ascendc::PlatformAscendC(platformInfo);
+        coreNum_ = ap.GetCoreNumAiv();
+        ap.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize_);
+
+        for (size_t i = 0; i < ctx_->GetComputeNodeInfo()->GetInputsNum(); ++i) {
+            auto shape = ctx_->GetInputShape(i);
+            OP_CHECK_NULL_WITH_CONTEXT(ctx_, shape);
+            std::vector<int64_t> dims; gert::Shape s = shape->GetStorageShape();
+            for (size_t d = 0; d < s.GetDimNum(); ++d) dims.push_back(s.GetDim(d));
+            if (dims.empty()) dims.push_back(1);  // rank0 标量当 1
+            raw_input_shapes_.push_back(dims);
+        }
+        for (size_t i = 0; i < ctx_->GetComputeNodeInfo()->GetOutputsNum(); ++i) {
+            auto shape = ctx_->GetOutputShape(i);
+            OP_CHECK_NULL_WITH_CONTEXT(ctx_, shape);
+            std::vector<int64_t> dims; gert::Shape s = shape->GetStorageShape();
+            for (size_t d = 0; d < s.GetDimNum(); ++d) dims.push_back(s.GetDim(d));
+            if (dims.empty()) dims.push_back(1);
+            raw_output_shapes_.push_back(dims);
+        }
+        auto inputDesc = ctx_->GetInputDesc(0);
+        OP_CHECK_NULL_WITH_CONTEXT(ctx_, inputDesc);
+        ge::DataType dtype = inputDesc->GetDataType();
+        const std::set<ge::DataType> sup = {ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_BF16, ge::DT_INT32, ge::DT_INT8, ge::DT_UINT8};
+        OP_CHECK_IF(sup.count(dtype) == 0, OP_LOGE(ctx_->GetNodeName(), "Unsupported dtype"), return ge::GRAPH_FAILED);
+
+        threshold_ = tgv2d::DEFAULT_THRESHOLD;
+        const auto* attrs = ctx_->GetAttrs();
+        if (attrs != nullptr) { const float* th = attrs->GetFloat(tgv2d::THRESHOLD_ATTR_IDX); if (th) threshold_ = *th; }
+
+        OP_CHECK_IF(!tgv2d::PadAndSqueeze(raw_input_shapes_, raw_output_shapes_, max_bro_shape_, normal_input_shapes_, normal_output_shapes_),
+            OP_LOGE(ctx_->GetNodeName(), "broadcast shape incompatible"), return ge::GRAPH_FAILED);
+        rank_ = (int64_t)max_bro_shape_.size();
+        OP_CHECK_IF(rank_ > 8, OP_LOGE(ctx_->GetNodeName(), "rank>8 unsupported"), return ge::GRAPH_FAILED);
+        return ge::GRAPH_SUCCESS;
+    }
+
+    template<int64_t R>
+    ge::graphStatus DoTilingAndSet() {
+        auto* tiling = ctx_->GetTilingData<ThresholdGradV2DTilingData<R>>();
+        OP_CHECK_NULL_WITH_CONTEXT(ctx_, tiling);
+        int64_t ub_per_core = (int64_t)ubSize_;
+        int64_t per_buf_bytes = (ub_per_core / kPhysNodes) & ~31LL;
+        tgv2d::FindSplitAxis(max_bro_shape_, ub_per_core, kPhysNodes, tiling->split);
+        tgv2d::MultiCoreSplit(max_bro_shape_, tiling->split, (int64_t)coreNum_, tiling->multicore);
+        tiling->per_buf_bytes = per_buf_bytes;
+        tiling->per_buf_elems = per_buf_bytes / 4;
+
+        int64_t num_in = (int64_t)normal_input_shapes_.size(), num_out = (int64_t)normal_output_shapes_.size();
+        std::vector<std::vector<int64_t>> in_strides(num_in), out_strides(num_out);
+        for (int64_t i = 0; i < num_in; i++)  tgv2d::PrecomputeStrides(normal_input_shapes_[i], in_strides[i]);
+        for (int64_t i = 0; i < num_out; i++) tgv2d::PrecomputeStrides(normal_output_shapes_[i], out_strides[i]);
+
+        tiling->rank = rank_;
+        tiling->threshold = threshold_;
+        int64_t delta = R - rank_;
+        for (int64_t d = 0; d < delta; d++) tiling->max_bro_shape[d] = 1;
+        for (int64_t d = 0; d < rank_; d++) tiling->max_bro_shape[d + delta] = max_bro_shape_[d];
+        tiling->split.axis += delta;
+        tiling->num_inputs = num_in; tiling->num_outputs = num_out;
+        for (int64_t i = 0; i < num_in; i++) {
+            for (int64_t d = 0; d < delta; d++) { tiling->input_shapes[i][d] = 1; tiling->input_strides[i][d] = 0; }
+            for (int64_t d = 0; d < rank_; d++) { tiling->input_shapes[i][d + delta] = normal_input_shapes_[i][d]; tiling->input_strides[i][d + delta] = in_strides[i][d]; }
+        }
+        for (int64_t i = num_in; i < kMaxInputSlots; i++) for (int64_t d = 0; d < R; d++) { tiling->input_shapes[i][d] = 1; tiling->input_strides[i][d] = 0; }
+        for (int64_t i = 0; i < num_out; i++) {
+            for (int64_t d = 0; d < delta; d++) { tiling->output_shapes[i][d] = 1; tiling->output_strides[i][d] = 0; }
+            for (int64_t d = 0; d < rank_; d++) { tiling->output_shapes[i][d + delta] = normal_output_shapes_[i][d]; tiling->output_strides[i][d + delta] = out_strides[i][d]; }
+        }
+        for (int64_t i = num_out; i < kMaxOutputSlots; i++) for (int64_t d = 0; d < R; d++) { tiling->output_shapes[i][d] = 1; tiling->output_strides[i][d] = 0; }
+
+        ctx_->SetBlockDim(tiling->multicore.num_cores);
+        OP_LOGI(ctx_->GetNodeName(), "TGV2D per_buf=%ld rank=%ld->R=%d mb=%s split(ax=%ld ai=%ld ao=%ld tail=%ld) mc(c=%ld t=%ld m=%ld ct=%ld)",
+            tiling->per_buf_bytes, rank_, (int)R, Arr2String(tiling->max_bro_shape, R).c_str(),
+            tiling->split.axis, tiling->split.a_i, tiling->split.a_o, tiling->split.a_i_tail,
+            tiling->multicore.num_cores, tiling->multicore.total_tiles, tiling->multicore.tiles_main, tiling->multicore.cores_tail);
+        return ge::GRAPH_SUCCESS;
+    }
+
+    gert::TilingContext* ctx_;
+    std::vector<std::vector<int64_t>> raw_input_shapes_, raw_output_shapes_;
+    std::vector<int64_t> max_bro_shape_;
+    std::vector<std::vector<int64_t>> normal_input_shapes_, normal_output_shapes_;
+    int64_t rank_ = 0; float threshold_ = 1.0f;
+    uint64_t coreNum_ = 0, ubSize_ = 0;
+};
+
+static ge::graphStatus ThresholdGradV2DTilingFunc(gert::TilingContext* context) {
+    ThresholdGradV2DTilingImpl impl(context);
+    auto ret = impl.RunTiling();
+    if (ret != ge::GRAPH_SUCCESS) return ret;
+    size_t* ws = context->GetWorkspaceSizes(1);
+    ws[0] = 0;
+    return ge::GRAPH_SUCCESS;
+}
+
+static ge::graphStatus TilingPrepareForThresholdGradV2D(gert::TilingParseContext* context) {
+    fe::PlatFormInfos* platformInfo = context->GetPlatformInfo();
+    auto compileInfo = context->GetCompiledInfo<ThresholdGradV2DCompileInfo>();
+    OP_CHECK_NULL_WITH_CONTEXT(context, platformInfo);
+    OP_CHECK_NULL_WITH_CONTEXT(context, compileInfo);
+    auto ap = platform_ascendc::PlatformAscendC(platformInfo);
+    compileInfo->coreNum = ap.GetCoreNumAiv();
+    ap.GetCoreMemSize(platform_ascendc::CoreMemType::UB, compileInfo->ubSize);
+    return ge::GRAPH_SUCCESS;
+}
+
+IMPL_OP_OPTILING(ThresholdGradV2D)
+    .Tiling(ThresholdGradV2DTilingFunc)
+    .TilingParse<ThresholdGradV2DCompileInfo>(TilingPrepareForThresholdGradV2D);
+
+} // namespace optiling

