+    param.SetMStep(static_cast<uint16_t>(mStep));
+    param.SetKStep(static_cast<uint16_t>(kStep));
+    param.SetSrcStride(static_cast<int32_t>(GCeilDiv(t.coutOpt, GN0)));
+    param.SetDstStride(static_cast<uint16_t>(mStep));
